def detect_loop(history, window=2):
    # same (sender, content) pair repeating = no progress
    seen = {}
    for msg in history:
        key = (msg.sender, msg.content.strip())
        seen[key] = seen.get(key, 0) + 1
        if seen[key] > window:
            return True
    return False

if detect_loop(conversation):
    raise RuntimeError("crew is looping; intervene or abort")
# catching non-progress early stops a silent budget burn

